public static void main(String[] args) throws Exception {
    Scanner sc = new Scanner(System.in);
    int n = sc.nextInt();
    int m = sc.nextInt();
    int[] a = new int[n];
    int[] b = new int[m];
    for (int i = 0; i < n; i++) a[i] = sc.nextInt();
    for (int i = 0; i < m; i++) b[i] = sc.nextInt();
    Arrays.sort(a);
    Arrays.sort(b);
    int i = 0, j = 0;
    long ans = 0;
    while (i < n && j < m) {
        if (b[j] <= a[i]) {
            j++;
            ans += a[i];
        }
        i++;
    }
    System.out.println(j == m ? ans : -1);
}
